import "server-only";
import { promises as fs } from "node:fs";
import path from "node:path";

// Minimal JSON-file store so the starter has no database dependency.
// Swap this module for a real database before deploying anywhere serious.
export type User = { id: string; email: string; passwordHash: string };
export type Session = { tokenHash: string; userId: string; expiresAt: number };
type Data = { users: User[]; sessions: Session[] };

const FILE = path.join(process.cwd(), "data", "db.json");

// Serialize read-modify-write cycles so concurrent requests don't clobber each other.
let queue: Promise<unknown> = Promise.resolve();

async function load(): Promise<Data> {
  try {
    return JSON.parse(await fs.readFile(FILE, "utf8"));
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === "ENOENT") return { users: [], sessions: [] };
    throw e;
  }
}

async function save(data: Data) {
  await fs.mkdir(path.dirname(FILE), { recursive: true });
  const tmp = `${FILE}.${process.pid}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(data), { mode: 0o600 });
  await fs.rename(tmp, FILE);
}

export function transaction<T>(fn: (data: Data) => T | Promise<T>): Promise<T> {
  const run = queue.then(async () => {
    const data = await load();
    const result = await fn(data);
    await save(data);
    return result;
  });
  queue = run.catch(() => {});
  return run;
}

export async function read<T>(fn: (data: Data) => T): Promise<T> {
  await queue;
  return fn(await load());
}
EOF
