"use server";

import { randomUUID } from "node:crypto";
import { redirect } from "next/navigation";
import { read, transaction } from "@/lib/db";
import { hashPassword, verifyPassword } from "@/lib/password";
import { createSession, destroySession } from "@/lib/session";

export type FormState = { error?: string } | undefined;

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MIN_PASSWORD = 8;
const MAX_PASSWORD = 128; // bounds scrypt work per request

// Used to spend the same time on unknown emails as on wrong passwords.
const DUMMY_HASH = hashPassword("dummy-password");

function credentials(formData: FormData) {
  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  const password = String(formData.get("password") ?? "");
  return { email, password };
}

export async function signup(_: FormState, formData: FormData): Promise<FormState> {
  const { email, password } = credentials(formData);
  if (!EMAIL_RE.test(email) || email.length > 254) return { error: "Enter a valid email address." };
  if (password.length < MIN_PASSWORD) return { error: `Password must be at least ${MIN_PASSWORD} characters.` };
  if (password.length > MAX_PASSWORD) return { error: `Password must be at most ${MAX_PASSWORD} characters.` };

  const passwordHash = await hashPassword(password);
  const id = randomUUID();
  const created = await transaction((data) => {
    if (data.users.some((u) => u.email === email)) return false;
    data.users.push({ id, email, passwordHash });
    return true;
  });
  if (!created) return { error: "An account with that email already exists." };

  await createSession(id);
  redirect("/dashboard");
}

export async function login(_: FormState, formData: FormData): Promise<FormState> {
  const { email, password } = credentials(formData);
  const invalid = { error: "Invalid email or password." };
  if (password.length > MAX_PASSWORD) return invalid;

  const user = await read((data) => data.users.find((u) => u.email === email));
  const ok = await verifyPassword(password, user ? user.passwordHash : await DUMMY_HASH);
  if (!user || !ok) return invalid;

  await createSession(user.id);
  redirect("/dashboard");
}

export async function logout() {
  await destroySession();
  redirect("/login");
}
EOF
